insert into listening_dialogues (id, level_id, lesson_id, turns, question_ja, options, correct_index)
values
  ('61177c59-f79b-574e-886b-0211e1277e96'::uuid, (select id from jlpt_levels where code = 'IT'), '98000000-0000-0000-0000-000000000001'::uuid, '[{"speaker": "B", "jp": "私は、E-LearningプロジェクトのPMのアンと申します。どうぞよろしくお願いいたします。"}, {"speaker": "A", "jp": "今回のプロジェクト責任者の小巻と申します。どうぞよろしくお願いいたします。"}, {"speaker": "B", "jp": "この度は、ご来社くださり、まことにありがとうございます。日本企業向けシステム開発部門を管理しております、ホアンと申します。どうぞよろしくお願いいたします。"}, {"speaker": "A", "jp": "私は、SESのIT部門でIT関連のプロジェクトを管理しています、小巻と申します。どうぞよろしくお願いいたします。"}, {"speaker": "B", "jp": "私は日本のお客様向けのシステム開発プロジェクトを主に担当しております。今回のプロジェクトのPMをつとめることになりました、アンと申します。どうぞよろしくお願いいたします。"}, {"speaker": "A", "jp": "今回は、皆さんとベトナムでプロジェクトのキックオフをするために参りましたので、2日間どうぞよろしくお願いします。"}, {"speaker": "B", "jp": "はい。弊社も対面でキックオフができて、光栄です。帰国されたあとに、SESのリーが要件定義の工程からオンサイトすることになっております。その際もよろしくお願いいたします。"}]'::jsonb, 'アンさんは何の仕事をしていますか。', '["SESのIT部門で、IT関連のプロジェクトを管理しています。", "日本のお客様向けのシステム開発プロジェクトを主に担当するPMです。", "ゲーム開発プロジェクトのテストを担当しています。", "日本企業向けのシステム開発部門を管理する責任者です。"]'::jsonb, 1),
  ('0fd1db1c-fecc-5109-8496-746926e828c1'::uuid, (select id from jlpt_levels where code = 'IT'), '98000000-0000-0000-0000-000000000001'::uuid, '[{"speaker": "B", "jp": "私は、E-LearningプロジェクトのPMのアンと申します。どうぞよろしくお願いいたします。"}, {"speaker": "A", "jp": "今回のプロジェクト責任者の小巻と申します。どうぞよろしくお願いいたします。"}, {"speaker": "B", "jp": "この度は、ご来社くださり、まことにありがとうございます。日本企業向けシステム開発部門を管理しております、ホアンと申します。どうぞよろしくお願いいたします。"}, {"speaker": "A", "jp": "私は、SESのIT部門でIT関連のプロジェクトを管理しています、小巻と申します。どうぞよろしくお願いいたします。"}, {"speaker": "B", "jp": "私は日本のお客様向けのシステム開発プロジェクトを主に担当しております。今回のプロジェクトのPMをつとめることになりました、アンと申します。どうぞよろしくお願いいたします。"}, {"speaker": "A", "jp": "今回は、皆さんとベトナムでプロジェクトのキックオフをするために参りましたので、2日間どうぞよろしくお願いします。"}, {"speaker": "B", "jp": "はい。弊社も対面でキックオフができて、光栄です。帰国されたあとに、SESのリーが要件定義の工程からオンサイトすることになっております。その際もよろしくお願いいたします。"}]'::jsonb, '小巻さんは何のためにベトナムに来ましたか。', '["要件定義の工程からオンサイトするためです。", "新しいシステムのテストをするためです。", "ベトナムでプロジェクトのキックオフをするためです。", "日本のお客様に製品のデモを見せるためです。"]'::jsonb, 2),
  ('aad04f99-3ea3-5823-9153-1cea3b16abf3'::uuid, (select id from jlpt_levels where code = 'IT'), '98000000-0000-0000-0000-000000000001'::uuid, '[{"speaker": "B", "jp": "私は、E-LearningプロジェクトのPMのアンと申します。どうぞよろしくお願いいたします。"}, {"speaker": "A", "jp": "今回のプロジェクト責任者の小巻と申します。どうぞよろしくお願いいたします。"}, {"speaker": "B", "jp": "この度は、ご来社くださり、まことにありがとうございます。日本企業向けシステム開発部門を管理しております、ホアンと申します。どうぞよろしくお願いいたします。"}, {"speaker": "A", "jp": "私は、SESのIT部門でIT関連のプロジェクトを管理しています、小巻と申します。どうぞよろしくお願いいたします。"}, {"speaker": "B", "jp": "私は日本のお客様向けのシステム開発プロジェクトを主に担当しております。今回のプロジェクトのPMをつとめることになりました、アンと申します。どうぞよろしくお願いいたします。"}, {"speaker": "A", "jp": "今回は、皆さんとベトナムでプロジェクトのキックオフをするために参りましたので、2日間どうぞよろしくお願いします。"}, {"speaker": "B", "jp": "はい。弊社も対面でキックオフができて、光栄です。帰国されたあとに、SESのリーが要件定義の工程からオンサイトすることになっております。その際もよろしくお願いいたします。"}]'::jsonb, 'アンさんは何が光栄だと言っていましたか。', '["日本の会社と新しく契約ができたことです。", "要件定義の工程からオンサイトできることです。", "名刺交換ができたことです。", "対面でキックオフができることです。"]'::jsonb, 3),
  ('d88728f2-4307-54e0-a33c-c6b24e9d8240'::uuid, (select id from jlpt_levels where code = 'IT'), '98000000-0000-0000-0000-000000000002'::uuid, '[{"speaker": "A", "jp": "では、プロジェクトのキックオフミーティングを始めたいと思います。よろしくお願いいたします。"}, {"speaker": "B", "jp": "はい、よろしくお願いいたします。"}, {"speaker": "A", "jp": "まず、本日のアジェンダについて説明いたします。最初に、SES様にプロジェクトの目的を説明していただきます。次に、弊社がキックオフ資料を説明いたします。そして、最後にQ&Aと相談をします。この順番で進めたいと思いますが、よろしいでしょうか。"}, {"speaker": "B", "jp": "はい。そうしましょう。ではまず、私から目的についてお話しします。今回はデジタル教科書のWebアプリケーションを開発します。動きのあるUIにすることで、生徒たちが楽しく学べるようにしたいと思っています。"}, {"speaker": "A", "jp": "ご説明ありがとうございます。それでは、私からキックオフ資料を説明いたします。"}, {"speaker": "A", "jp": "こちらをご覧ください。キックオフ資料の内容は、プロジェクトの概要、体制、開発手法、スケジュール、コミュニケーションプラン、リスクと課題です。では、順を追って説明いたします。"}, {"speaker": "B", "jp": "はい。お願いします。"}, {"speaker": "A", "jp": "まず、プロジェクト概要についてです。今回のE-Learningプロジェクトは、Webアプリを開発するプロジェクトです。既存システムをベースに、WebGLを取り入れて機能追加と変更をします。"}]'::jsonb, '会議の中でSES社は何を説明しますか。', '["キックオフ資料です。", "プロジェクトの体制です。", "プロジェクトの目的です。", "スケジュールとリスクです。"]'::jsonb, 2),
  ('24b88d33-3803-5f2d-8852-6eb442e85174'::uuid, (select id from jlpt_levels where code = 'IT'), '98000000-0000-0000-0000-000000000002'::uuid, '[{"speaker": "A", "jp": "では、プロジェクトのキックオフミーティングを始めたいと思います。よろしくお願いいたします。"}, {"speaker": "B", "jp": "はい、よろしくお願いいたします。"}, {"speaker": "A", "jp": "まず、本日のアジェンダについて説明いたします。最初に、SES様にプロジェクトの目的を説明していただきます。次に、弊社がキックオフ資料を説明いたします。そして、最後にQ&Aと相談をします。この順番で進めたいと思いますが、よろしいでしょうか。"}, {"speaker": "B", "jp": "はい。そうしましょう。ではまず、私から目的についてお話しします。今回はデジタル教科書のWebアプリケーションを開発します。動きのあるUIにすることで、生徒たちが楽しく学べるようにしたいと思っています。"}, {"speaker": "A", "jp": "ご説明ありがとうございます。それでは、私からキックオフ資料を説明いたします。"}, {"speaker": "A", "jp": "こちらをご覧ください。キックオフ資料の内容は、プロジェクトの概要、体制、開発手法、スケジュール、コミュニケーションプラン、リスクと課題です。では、順を追って説明いたします。"}, {"speaker": "B", "jp": "はい。お願いします。"}, {"speaker": "A", "jp": "まず、プロジェクト概要についてです。今回のE-Learningプロジェクトは、Webアプリを開発するプロジェクトです。既存システムをベースに、WebGLを取り入れて機能追加と変更をします。"}]'::jsonb, '今回のプロジェクトの目的は何ですか。', '["既存のシステムを新しいシステムに入れ替えて、費用を減らすことです。", "E-Learningのデスクトップアプリを海外で販売することです。", "成績を自動で計算して、先生の仕事を減らすことです。", "デジタル教科書のWebアプリケーションを開発し、生徒たちが楽しく学べるようにすることです。"]'::jsonb, 3),
  ('4e8a0898-4646-55e3-a5e9-5a04671a3031'::uuid, (select id from jlpt_levels where code = 'IT'), '98000000-0000-0000-0000-000000000002'::uuid, '[{"speaker": "A", "jp": "では、プロジェクトのキックオフミーティングを始めたいと思います。よろしくお願いいたします。"}, {"speaker": "B", "jp": "はい、よろしくお願いいたします。"}, {"speaker": "A", "jp": "まず、本日のアジェンダについて説明いたします。最初に、SES様にプロジェクトの目的を説明していただきます。次に、弊社がキックオフ資料を説明いたします。そして、最後にQ&Aと相談をします。この順番で進めたいと思いますが、よろしいでしょうか。"}, {"speaker": "B", "jp": "はい。そうしましょう。ではまず、私から目的についてお話しします。今回はデジタル教科書のWebアプリケーションを開発します。動きのあるUIにすることで、生徒たちが楽しく学べるようにしたいと思っています。"}, {"speaker": "A", "jp": "ご説明ありがとうございます。それでは、私からキックオフ資料を説明いたします。"}, {"speaker": "A", "jp": "こちらをご覧ください。キックオフ資料の内容は、プロジェクトの概要、体制、開発手法、スケジュール、コミュニケーションプラン、リスクと課題です。では、順を追って説明いたします。"}, {"speaker": "B", "jp": "はい。お願いします。"}, {"speaker": "A", "jp": "まず、プロジェクト概要についてです。今回のE-Learningプロジェクトは、Webアプリを開発するプロジェクトです。既存システムをベースに、WebGLを取り入れて機能追加と変更をします。"}]'::jsonb, 'キックオフ資料は何について書いてありますか。', '["プロジェクトの概要、体制、開発手法、スケジュール、コミュニケーションプラン、リスクと課題です。", "プロジェクトの目的、予算、契約の条件、納品日、サポート体制です。", "概要、体制、要件定義、テスト計画、リリースノート、費用です。", "目的、開発手法、スケジュール、見積り、契約、品質保証です。"]'::jsonb, 0),
  ('19609e0f-c0cf-52c9-924e-d7ccdba80970'::uuid, (select id from jlpt_levels where code = 'IT'), '98000000-0000-0000-0000-000000000003'::uuid, '[{"speaker": "A", "jp": "次に、マスタースケジュールと進め方について説明いたします。開発期間は4月1日から7月8日までです。SRS、UIなどインプットは御社より提供していただき、弊社がコーディング、UT、ITをベトナムで行います。SEのリーダーは要件定義からオンサイトし、UATとデプロイメントもサポートします。"}, {"speaker": "B", "jp": "はい。SRSは完成しましたので、明日説明します。UIは弊社で準備していますが、開発期間中、ロジックに合わせて直したほうがよいものがありましたら、教えていただければと思います。"}, {"speaker": "A", "jp": "承知しました。開発手法に関しては要件がかなりはっきりしているので、ウォーターフォールで開発を進めます。"}, {"speaker": "B", "jp": "はい。そうですね。少しは要件の変更が発生するかもしれませんが、ほぼ決まっていますので、それで問題ないと思います。"}, {"speaker": "A", "jp": "はい。ありがとうございます。また、UIが御社の期待通りになっているかをチェックするため、3回のデモを実施することを提案します。そこで、修正すべき点を確認し、必要であれば修正します。そうすれば、手戻りを減らせると考えています。"}, {"speaker": "B", "jp": "そうですね。賛成です。実は、SRSで一部決まっていない内容があります。デモで何を改善すればよいか、はっきり見えるようになり、より良い製品ができると思いますので、ぜひ行いましょう。"}]'::jsonb, 'プロジェクトの開発期間はいつからいつまでですか。', '["4月8日から7月1日までです。", "4月1日から8月8日までです。", "3月1日から7月8日までです。", "4月1日から7月8日までです。"]'::jsonb, 3),
  ('fbd7fb57-4006-5b06-a900-12d81a9e08e1'::uuid, (select id from jlpt_levels where code = 'IT'), '98000000-0000-0000-0000-000000000003'::uuid, '[{"speaker": "A", "jp": "次に、マスタースケジュールと進め方について説明いたします。開発期間は4月1日から7月8日までです。SRS、UIなどインプットは御社より提供していただき、弊社がコーディング、UT、ITをベトナムで行います。SEのリーダーは要件定義からオンサイトし、UATとデプロイメントもサポートします。"}, {"speaker": "B", "jp": "はい。SRSは完成しましたので、明日説明します。UIは弊社で準備していますが、開発期間中、ロジックに合わせて直したほうがよいものがありましたら、教えていただければと思います。"}, {"speaker": "A", "jp": "承知しました。開発手法に関しては要件がかなりはっきりしているので、ウォーターフォールで開発を進めます。"}, {"speaker": "B", "jp": "はい。そうですね。少しは要件の変更が発生するかもしれませんが、ほぼ決まっていますので、それで問題ないと思います。"}, {"speaker": "A", "jp": "はい。ありがとうございます。また、UIが御社の期待通りになっているかをチェックするため、3回のデモを実施することを提案します。そこで、修正すべき点を確認し、必要であれば修正します。そうすれば、手戻りを減らせると考えています。"}, {"speaker": "B", "jp": "そうですね。賛成です。実は、SRSで一部決まっていない内容があります。デモで何を改善すればよいか、はっきり見えるようになり、より良い製品ができると思いますので、ぜひ行いましょう。"}]'::jsonb, 'UIは開発の過程で修正してもよいことになっていますか。', '["はい。ロジックに合わせて直したほうがよいものがあれば、教えてもらうことになっています。", "いいえ。UIはお客様が準備したので、修正できません。", "いいえ。修正するのは、デモがすべて終わってからです。", "はい。ただし、修正はお客様が自分で行います。"]'::jsonb, 0),
  ('1e11d187-40f2-5228-8ad3-6bf613c3a61e'::uuid, (select id from jlpt_levels where code = 'IT'), '98000000-0000-0000-0000-000000000003'::uuid, '[{"speaker": "A", "jp": "次に、マスタースケジュールと進め方について説明いたします。開発期間は4月1日から7月8日までです。SRS、UIなどインプットは御社より提供していただき、弊社がコーディング、UT、ITをベトナムで行います。SEのリーダーは要件定義からオンサイトし、UATとデプロイメントもサポートします。"}, {"speaker": "B", "jp": "はい。SRSは完成しましたので、明日説明します。UIは弊社で準備していますが、開発期間中、ロジックに合わせて直したほうがよいものがありましたら、教えていただければと思います。"}, {"speaker": "A", "jp": "承知しました。開発手法に関しては要件がかなりはっきりしているので、ウォーターフォールで開発を進めます。"}, {"speaker": "B", "jp": "はい。そうですね。少しは要件の変更が発生するかもしれませんが、ほぼ決まっていますので、それで問題ないと思います。"}, {"speaker": "A", "jp": "はい。ありがとうございます。また、UIが御社の期待通りになっているかをチェックするため、3回のデモを実施することを提案します。そこで、修正すべき点を確認し、必要であれば修正します。そうすれば、手戻りを減らせると考えています。"}, {"speaker": "B", "jp": "そうですね。賛成です。実は、SRSで一部決まっていない内容があります。デモで何を改善すればよいか、はっきり見えるようになり、より良い製品ができると思いますので、ぜひ行いましょう。"}]'::jsonb, 'プロジェクトでは、手戻りを減らすためにどんなことをする予定ですか。', '["要件をもう一度すべて書き直します。", "3回のデモを実施して、修正すべき点を確認します。", "設計工程を増やして、詳しい設計書を作ります。", "毎週お客様の会社に行って、進捗を報告します。"]'::jsonb, 1),
  ('c838ac8e-11a3-5f0c-bb66-43b5a02acb1e'::uuid, (select id from jlpt_levels where code = 'IT'), '98000000-0000-0000-0000-000000000004'::uuid, '[{"speaker": "A", "jp": "ここまでプロジェクト概要と開発手法について説明しましたが、何かご質問はありますか。ご質問がなければ、体制とメンバーについて紹介いたします。"}, {"speaker": "B", "jp": "ここまでは問題ないので、続けてください。"}, {"speaker": "A", "jp": "はい。こちらがプロジェクトの体制です。黒田様がプロジェクト統括管理者で、小巻様が御社のPMです。このプロジェクトに関係する課題などは私が小巻様と確認すればよいという理解ですが、間違いないでしょうか。"}, {"speaker": "B", "jp": "はい。その通りです。今回のプロジェクトは設計工程がなく、何度かデモをしてお互いの認識を確認するという方法で進めます。そうすると、ひんぱんに質問のやりとりをする必要が出てくると思います。日本にはリーさんもいらっしゃいますし、確認したいことがあったら、いつでもけっこうですので、遠慮なく聞いてください。"}, {"speaker": "A", "jp": "はい。ありがとうございます。オフショアの体制ですが、統括管理者はホアンです。PMは私アンで、開発、テスト、コミュニケーション、品質保証の4つのチームを管理します。そして、SEのリーが御社にオンサイトします。レポートラインですが、メンバーがチームリーダーに報告し、チームリーダーが私に報告します。私がそれらの情報をまとめて、小巻様に報告します。"}, {"speaker": "B", "jp": "わかりました。レポートラインについては弊社も同じ認識です。"}, {"speaker": "A", "jp": "技術的な問題は、私もしくはリーが確認します。営業と契約に関しては当初から御社とやりとりをさせていただいているリンが引き続き担当します。プロジェクトで解決の難しい課題があれば、黒田様、ホアンにエスカレーションします。場合によっては、リンも参加いたします。"}, {"speaker": "B", "jp": "はい。わかりました。ご説明ありがとうございました。"}]'::jsonb, 'プロジェクトで課題が発生した場合は、誰と誰が確認しますか。', '["技術的な課題はアンさんかリーさんが確認し、難しい課題は黒田様とホアンさんにエスカレーションします。", "課題はすべて、小巻様とリンさんが確認します。", "課題はチームリーダーがホアンさんに直接報告して解決します。", "技術的な課題も営業の課題も、リンさんが一人で確認します。"]'::jsonb, 0),
  ('1bb27c44-6361-5d14-a9b4-9fb3f81a0ab5'::uuid, (select id from jlpt_levels where code = 'IT'), '98000000-0000-0000-0000-000000000004'::uuid, '[{"speaker": "A", "jp": "ここまでプロジェクト概要と開発手法について説明しましたが、何かご質問はありますか。ご質問がなければ、体制とメンバーについて紹介いたします。"}, {"speaker": "B", "jp": "ここまでは問題ないので、続けてください。"}, {"speaker": "A", "jp": "はい。こちらがプロジェクトの体制です。黒田様がプロジェクト統括管理者で、小巻様が御社のPMです。このプロジェクトに関係する課題などは私が小巻様と確認すればよいという理解ですが、間違いないでしょうか。"}, {"speaker": "B", "jp": "はい。その通りです。今回のプロジェクトは設計工程がなく、何度かデモをしてお互いの認識を確認するという方法で進めます。そうすると、ひんぱんに質問のやりとりをする必要が出てくると思います。日本にはリーさんもいらっしゃいますし、確認したいことがあったら、いつでもけっこうですので、遠慮なく聞いてください。"}, {"speaker": "A", "jp": "はい。ありがとうございます。オフショアの体制ですが、統括管理者はホアンです。PMは私アンで、開発、テスト、コミュニケーション、品質保証の4つのチームを管理します。そして、SEのリーが御社にオンサイトします。レポートラインですが、メンバーがチームリーダーに報告し、チームリーダーが私に報告します。私がそれらの情報をまとめて、小巻様に報告します。"}, {"speaker": "B", "jp": "わかりました。レポートラインについては弊社も同じ認識です。"}, {"speaker": "A", "jp": "技術的な問題は、私もしくはリーが確認します。営業と契約に関しては当初から御社とやりとりをさせていただいているリンが引き続き担当します。プロジェクトで解決の難しい課題があれば、黒田様、ホアンにエスカレーションします。場合によっては、リンも参加いたします。"}, {"speaker": "B", "jp": "はい。わかりました。ご説明ありがとうございました。"}]'::jsonb, 'プロジェクトのレポートラインについて教えてください。', '["メンバーがアンさんに直接報告し、アンさんがホアンさんに報告します。", "メンバーがチームリーダーに報告し、チームリーダーがアンさんに報告し、アンさんが小巻様に報告します。", "チームリーダーが小巻様に直接報告し、小巻様がアンさんに伝えます。", "メンバーがリーさんに報告し、リーさんが黒田様に報告します。"]'::jsonb, 1),
  ('2aa2dba3-c660-5c52-bcfe-471575bdde74'::uuid, (select id from jlpt_levels where code = 'IT'), '98000000-0000-0000-0000-000000000004'::uuid, '[{"speaker": "A", "jp": "ここまでプロジェクト概要と開発手法について説明しましたが、何かご質問はありますか。ご質問がなければ、体制とメンバーについて紹介いたします。"}, {"speaker": "B", "jp": "ここまでは問題ないので、続けてください。"}, {"speaker": "A", "jp": "はい。こちらがプロジェクトの体制です。黒田様がプロジェクト統括管理者で、小巻様が御社のPMです。このプロジェクトに関係する課題などは私が小巻様と確認すればよいという理解ですが、間違いないでしょうか。"}, {"speaker": "B", "jp": "はい。その通りです。今回のプロジェクトは設計工程がなく、何度かデモをしてお互いの認識を確認するという方法で進めます。そうすると、ひんぱんに質問のやりとりをする必要が出てくると思います。日本にはリーさんもいらっしゃいますし、確認したいことがあったら、いつでもけっこうですので、遠慮なく聞いてください。"}, {"speaker": "A", "jp": "はい。ありがとうございます。オフショアの体制ですが、統括管理者はホアンです。PMは私アンで、開発、テスト、コミュニケーション、品質保証の4つのチームを管理します。そして、SEのリーが御社にオンサイトします。レポートラインですが、メンバーがチームリーダーに報告し、チームリーダーが私に報告します。私がそれらの情報をまとめて、小巻様に報告します。"}, {"speaker": "B", "jp": "わかりました。レポートラインについては弊社も同じ認識です。"}, {"speaker": "A", "jp": "技術的な問題は、私もしくはリーが確認します。営業と契約に関しては当初から御社とやりとりをさせていただいているリンが引き続き担当します。プロジェクトで解決の難しい課題があれば、黒田様、ホアンにエスカレーションします。場合によっては、リンも参加いたします。"}, {"speaker": "B", "jp": "はい。わかりました。ご説明ありがとうございました。"}]'::jsonb, 'リンさんは何を担当しますか。', '["技術的な問題の確認を担当します。", "開発、テスト、コミュニケーション、品質保証の4つのチームを管理します。", "営業と契約を担当します。", "お客様の会社にオンサイトして、要件定義をします。"]'::jsonb, 2),
  ('49f05ad8-eeff-59a9-8c89-2e07a71e255f'::uuid, (select id from jlpt_levels where code = 'IT'), '98000000-0000-0000-0000-000000000005'::uuid, '[{"speaker": "B", "jp": "紹介します。プロジェクト実施のためにベトナムから来てくださったDKH社のリーさんです。本日からこちらで勤務していただきます。では、リーさん、簡単に自己紹介をお願いします。"}, {"speaker": "A", "jp": "本日よりお世話になります。ベトナムから参りました、リーと申します。DKHでSEをしております。日本は初めてですので、わからないことも多いかと思いますが、どうぞよろしくお願いいたします。"}, {"speaker": "B", "jp": "困ったことがあったら、私や山本に遠慮なく相談してください。"}, {"speaker": "A", "jp": "はい。ありがとうございます。こちらはホアンからのおみやげです。どうぞ皆さんで召し上がってください。ホアンも皆さんによろしくと申しておりました。"}, {"speaker": "B", "jp": "お気遣いありがとうございます。これはベトナムで有名なお菓子か何かですか。"}, {"speaker": "A", "jp": "はい。北部の名物で、緑豆からできたお菓子です。"}, {"speaker": "A", "jp": "ところで、御社のルールについて教えていただけますか。"}, {"speaker": "B", "jp": "そうですね。山本から説明しましょう。"}, {"speaker": "B", "jp": "まず、勤務時間は、朝9時から夕方6時までです。だいたい皆さん10分前には出社しています。"}, {"speaker": "A", "jp": "承知しました。9時から6時までですね。お昼休みは何時から取ればよいですか。"}, {"speaker": "B", "jp": "一応12時から1時ですが、外のお店は混むので、少しずらして取っても問題ありません。"}, {"speaker": "A", "jp": "ずらしてというのは、どういうことですか。"}, {"speaker": "B", "jp": "例えば、12時半から1時半にするとか、1時から2時にしてもかまわないということです。1時間であればよいです。会議室と給湯室へも案内しましょう。"}]'::jsonb, 'リーさんが持って行ったおみやげは何ですか。', '["南部の名物で、米からできたお菓子です。", "北部の名物で、緑豆からできたお菓子です。", "ベトナムで有名なコーヒーです。", "北部の名物で、果物を使ったお菓子です。"]'::jsonb, 1),
  ('f6eb9205-d6df-5f20-9a21-7d70c4881995'::uuid, (select id from jlpt_levels where code = 'IT'), '98000000-0000-0000-0000-000000000005'::uuid, '[{"speaker": "B", "jp": "紹介します。プロジェクト実施のためにベトナムから来てくださったDKH社のリーさんです。本日からこちらで勤務していただきます。では、リーさん、簡単に自己紹介をお願いします。"}, {"speaker": "A", "jp": "本日よりお世話になります。ベトナムから参りました、リーと申します。DKHでSEをしております。日本は初めてですので、わからないことも多いかと思いますが、どうぞよろしくお願いいたします。"}, {"speaker": "B", "jp": "困ったことがあったら、私や山本に遠慮なく相談してください。"}, {"speaker": "A", "jp": "はい。ありがとうございます。こちらはホアンからのおみやげです。どうぞ皆さんで召し上がってください。ホアンも皆さんによろしくと申しておりました。"}, {"speaker": "B", "jp": "お気遣いありがとうございます。これはベトナムで有名なお菓子か何かですか。"}, {"speaker": "A", "jp": "はい。北部の名物で、緑豆からできたお菓子です。"}, {"speaker": "A", "jp": "ところで、御社のルールについて教えていただけますか。"}, {"speaker": "B", "jp": "そうですね。山本から説明しましょう。"}, {"speaker": "B", "jp": "まず、勤務時間は、朝9時から夕方6時までです。だいたい皆さん10分前には出社しています。"}, {"speaker": "A", "jp": "承知しました。9時から6時までですね。お昼休みは何時から取ればよいですか。"}, {"speaker": "B", "jp": "一応12時から1時ですが、外のお店は混むので、少しずらして取っても問題ありません。"}, {"speaker": "A", "jp": "ずらしてというのは、どういうことですか。"}, {"speaker": "B", "jp": "例えば、12時半から1時半にするとか、1時から2時にしてもかまわないということです。1時間であればよいです。会議室と給湯室へも案内しましょう。"}]'::jsonb, 'SESの勤務時間について教えてください。', '["朝10時から夕方6時までです。", "朝9時から夕方5時までです。", "朝9時から夕方6時までです。", "朝8時半から夕方5時半までです。"]'::jsonb, 2),
  ('d5316a39-0afd-5ac3-9c6b-285c9f3f3eb5'::uuid, (select id from jlpt_levels where code = 'IT'), '98000000-0000-0000-0000-000000000005'::uuid, '[{"speaker": "B", "jp": "紹介します。プロジェクト実施のためにベトナムから来てくださったDKH社のリーさんです。本日からこちらで勤務していただきます。では、リーさん、簡単に自己紹介をお願いします。"}, {"speaker": "A", "jp": "本日よりお世話になります。ベトナムから参りました、リーと申します。DKHでSEをしております。日本は初めてですので、わからないことも多いかと思いますが、どうぞよろしくお願いいたします。"}, {"speaker": "B", "jp": "困ったことがあったら、私や山本に遠慮なく相談してください。"}, {"speaker": "A", "jp": "はい。ありがとうございます。こちらはホアンからのおみやげです。どうぞ皆さんで召し上がってください。ホアンも皆さんによろしくと申しておりました。"}, {"speaker": "B", "jp": "お気遣いありがとうございます。これはベトナムで有名なお菓子か何かですか。"}, {"speaker": "A", "jp": "はい。北部の名物で、緑豆からできたお菓子です。"}, {"speaker": "A", "jp": "ところで、御社のルールについて教えていただけますか。"}, {"speaker": "B", "jp": "そうですね。山本から説明しましょう。"}, {"speaker": "B", "jp": "まず、勤務時間は、朝9時から夕方6時までです。だいたい皆さん10分前には出社しています。"}, {"speaker": "A", "jp": "承知しました。9時から6時までですね。お昼休みは何時から取ればよいですか。"}, {"speaker": "B", "jp": "一応12時から1時ですが、外のお店は混むので、少しずらして取っても問題ありません。"}, {"speaker": "A", "jp": "ずらしてというのは、どういうことですか。"}, {"speaker": "B", "jp": "例えば、12時半から1時半にするとか、1時から2時にしてもかまわないということです。1時間であればよいです。会議室と給湯室へも案内しましょう。"}]'::jsonb, 'これからリーさんたちはどこに行きますか。', '["食堂と会議室に行きます。", "給湯室と更衣室に行きます。", "IT部門の部屋と倉庫に行きます。", "会議室と給湯室に行きます。"]'::jsonb, 3),
  ('ff23f89a-c94b-5711-9a61-d3c43b6f2393'::uuid, (select id from jlpt_levels where code = 'IT'), '98000000-0000-0000-0000-000000000006'::uuid, '[{"speaker": "B", "jp": "こちらの会議室はIT部門の専用です。使いたいときは、事前に会議室予約システムから予約してください。後で予約サイトのリンクを送っておきますね。"}, {"speaker": "A", "jp": "はい。オフショアチームとの会議もあるので、ありがとうございます。"}, {"speaker": "B", "jp": "こちらは給湯室です。このポットのお湯は自由にお使いください。そして、冷蔵庫は共用ですので、ものを入れるときは自分の名前を書いて、賞味期限切れのものは処分するようにしてくださいね。ごみは生ごみやペットボトルなどに分別することになっています。"}, {"speaker": "A", "jp": "分別というのは、ものによって、これらのごみ箱に分けて捨てるということですね。"}, {"speaker": "B", "jp": "そうです。他になにか気になることはありますか。"}, {"speaker": "A", "jp": "すぐには思いつかないので、逆に質問してもよいですか。御社で他になにか気をつけた方がよいことはありませんか。"}, {"speaker": "B", "jp": "そうですね。整理整頓とセキュリティですかね。席を離れるときは、机の上に社外秘の資料などを置いたままにしないようにしてください。また、退社するときは、ノートパソコンを鍵付きロッカーに入れて帰ってください。"}, {"speaker": "A", "jp": "はい。気をつけます。"}, {"speaker": "B", "jp": "では、席に戻ってパソコンの設定をしましょうか。弊社で指定されているウイルス対策ソフトやメール誤送信防止ツールをインストールしましょう。"}, {"speaker": "A", "jp": "これが持参したノートパソコンです。ベトナムにいる間に、必要なデータはバックアップを取ってあります。"}, {"speaker": "B", "jp": "では、一度お預かりしましょう。弊社では、IT部門のセキュリティチェックを受けてからでないと、社内で使ってはいけないことになっています。"}, {"speaker": "A", "jp": "承知しました。では、お願いします。"}]'::jsonb, '給湯室で冷蔵庫にものを入れるときの注意点は何ですか。', '["冷蔵庫に入れたものは、毎日夕方に全部持って帰ります。", "ものを入れる前に、事前に予約システムで予約します。", "ものを入れるときは自分の名前を書いて、賞味期限切れのものは処分します。", "名前は書かないで、みんなのものとして使います。"]'::jsonb, 2),
  ('0b15b0a1-c3e2-5f76-addb-2ae30fc29b75'::uuid, (select id from jlpt_levels where code = 'IT'), '98000000-0000-0000-0000-000000000006'::uuid, '[{"speaker": "B", "jp": "こちらの会議室はIT部門の専用です。使いたいときは、事前に会議室予約システムから予約してください。後で予約サイトのリンクを送っておきますね。"}, {"speaker": "A", "jp": "はい。オフショアチームとの会議もあるので、ありがとうございます。"}, {"speaker": "B", "jp": "こちらは給湯室です。このポットのお湯は自由にお使いください。そして、冷蔵庫は共用ですので、ものを入れるときは自分の名前を書いて、賞味期限切れのものは処分するようにしてくださいね。ごみは生ごみやペットボトルなどに分別することになっています。"}, {"speaker": "A", "jp": "分別というのは、ものによって、これらのごみ箱に分けて捨てるということですね。"}, {"speaker": "B", "jp": "そうです。他になにか気になることはありますか。"}, {"speaker": "A", "jp": "すぐには思いつかないので、逆に質問してもよいですか。御社で他になにか気をつけた方がよいことはありませんか。"}, {"speaker": "B", "jp": "そうですね。整理整頓とセキュリティですかね。席を離れるときは、机の上に社外秘の資料などを置いたままにしないようにしてください。また、退社するときは、ノートパソコンを鍵付きロッカーに入れて帰ってください。"}, {"speaker": "A", "jp": "はい。気をつけます。"}, {"speaker": "B", "jp": "では、席に戻ってパソコンの設定をしましょうか。弊社で指定されているウイルス対策ソフトやメール誤送信防止ツールをインストールしましょう。"}, {"speaker": "A", "jp": "これが持参したノートパソコンです。ベトナムにいる間に、必要なデータはバックアップを取ってあります。"}, {"speaker": "B", "jp": "では、一度お預かりしましょう。弊社では、IT部門のセキュリティチェックを受けてからでないと、社内で使ってはいけないことになっています。"}, {"speaker": "A", "jp": "承知しました。では、お願いします。"}]'::jsonb, '退社するときは、何をすればよいですか。', '["ノートパソコンを机の上に置いたまま帰ります。", "ノートパソコンをIT部門に預けて帰ります。", "社外秘の資料を机の引き出しに入れて帰ります。", "ノートパソコンを鍵付きロッカーに入れて帰ります。"]'::jsonb, 3),
  ('328783fe-80ff-56cf-8721-c3bb9c223a66'::uuid, (select id from jlpt_levels where code = 'IT'), '98000000-0000-0000-0000-000000000006'::uuid, '[{"speaker": "B", "jp": "こちらの会議室はIT部門の専用です。使いたいときは、事前に会議室予約システムから予約してください。後で予約サイトのリンクを送っておきますね。"}, {"speaker": "A", "jp": "はい。オフショアチームとの会議もあるので、ありがとうございます。"}, {"speaker": "B", "jp": "こちらは給湯室です。このポットのお湯は自由にお使いください。そして、冷蔵庫は共用ですので、ものを入れるときは自分の名前を書いて、賞味期限切れのものは処分するようにしてくださいね。ごみは生ごみやペットボトルなどに分別することになっています。"}, {"speaker": "A", "jp": "分別というのは、ものによって、これらのごみ箱に分けて捨てるということですね。"}, {"speaker": "B", "jp": "そうです。他になにか気になることはありますか。"}, {"speaker": "A", "jp": "すぐには思いつかないので、逆に質問してもよいですか。御社で他になにか気をつけた方がよいことはありませんか。"}, {"speaker": "B", "jp": "そうですね。整理整頓とセキュリティですかね。席を離れるときは、机の上に社外秘の資料などを置いたままにしないようにしてください。また、退社するときは、ノートパソコンを鍵付きロッカーに入れて帰ってください。"}, {"speaker": "A", "jp": "はい。気をつけます。"}, {"speaker": "B", "jp": "では、席に戻ってパソコンの設定をしましょうか。弊社で指定されているウイルス対策ソフトやメール誤送信防止ツールをインストールしましょう。"}, {"speaker": "A", "jp": "これが持参したノートパソコンです。ベトナムにいる間に、必要なデータはバックアップを取ってあります。"}, {"speaker": "B", "jp": "では、一度お預かりしましょう。弊社では、IT部門のセキュリティチェックを受けてからでないと、社内で使ってはいけないことになっています。"}, {"speaker": "A", "jp": "承知しました。では、お願いします。"}]'::jsonb, '持参したノートパソコンを使用するにはどうすればよいですか。', '["IT部門のセキュリティチェックを受けてから使用します。", "会議室予約システムで事前に予約してから使用します。", "必要なデータをバックアップしたら、すぐに使ってもよいです。", "ウイルス対策ソフトを自分で選んでインストールしてから使用します。"]'::jsonb, 0),
  ('30120612-74f0-56be-9285-67285429326c'::uuid, (select id from jlpt_levels where code = 'IT'), '98000000-0000-0000-0000-000000000007'::uuid, '[{"speaker": "B", "jp": "プロジェクトのメンバーが全員そろいましたので、要件の説明会を始めたいと思います。説明の中で、わかりにくいところや確認しておきたいことがありましたら、その場で質問してください。"}, {"speaker": "A", "jp": "承知しました。よろしくお願いいたします。"}, {"speaker": "B", "jp": "昨年は、デジタル教科書のデスクトップアプリケーションを開発していただき、ありがとうございました。キックオフミーティングで説明した通り、今回はこのアプリをベースに、WebGLを使用してアプリをWeb化し、一部機能の追加・修正を行います。"}, {"speaker": "B", "jp": "まず、今回のWeb版の画面について説明します。お見せしているファイルは昨年開発されたアプリの資料なので、皆さんにとってはなじみのあるものだと思います。新規画面には、「新規」と、Web版で実装しなくてよいものには「Web化対象外」と追記しました。"}, {"speaker": "A", "jp": "はい。「新規」または「Web化対象外」の追記がない場合は、以前のアプリと同じ画面にするということですね。"}, {"speaker": "B", "jp": "その通りです。"}, {"speaker": "B", "jp": "また、機能の修正点がいくつかあるので、別のファイルにまとめました。"}, {"speaker": "A", "jp": "はい。「Web化_修正点」というものですか。"}, {"speaker": "B", "jp": "はい、そうです。"}, {"speaker": "A", "jp": "そのファイルであれば、すでに読んでいますので、この場で説明していただかなくても問題ありません。疑問点がでてきたら、確認させてください。"}, {"speaker": "B", "jp": "わかりました。今後、実装中に何かありましたら、遠慮なくいつでも聞いてください。"}]'::jsonb, '昨年開発チームは何を開発しましたか。', '["デジタル教科書のWebアプリケーションを開発しました。", "学習データを保存するWebサイトを開発しました。", "WebGLの新しいライブラリを開発しました。", "デジタル教科書のデスクトップアプリケーションを開発しました。"]'::jsonb, 3),
  ('b02fd1da-3b12-5370-a2c6-ab5beb9c95ea'::uuid, (select id from jlpt_levels where code = 'IT'), '98000000-0000-0000-0000-000000000007'::uuid, '[{"speaker": "B", "jp": "プロジェクトのメンバーが全員そろいましたので、要件の説明会を始めたいと思います。説明の中で、わかりにくいところや確認しておきたいことがありましたら、その場で質問してください。"}, {"speaker": "A", "jp": "承知しました。よろしくお願いいたします。"}, {"speaker": "B", "jp": "昨年は、デジタル教科書のデスクトップアプリケーションを開発していただき、ありがとうございました。キックオフミーティングで説明した通り、今回はこのアプリをベースに、WebGLを使用してアプリをWeb化し、一部機能の追加・修正を行います。"}, {"speaker": "B", "jp": "まず、今回のWeb版の画面について説明します。お見せしているファイルは昨年開発されたアプリの資料なので、皆さんにとってはなじみのあるものだと思います。新規画面には、「新規」と、Web版で実装しなくてよいものには「Web化対象外」と追記しました。"}, {"speaker": "A", "jp": "はい。「新規」または「Web化対象外」の追記がない場合は、以前のアプリと同じ画面にするということですね。"}, {"speaker": "B", "jp": "その通りです。"}, {"speaker": "B", "jp": "また、機能の修正点がいくつかあるので、別のファイルにまとめました。"}, {"speaker": "A", "jp": "はい。「Web化_修正点」というものですか。"}, {"speaker": "B", "jp": "はい、そうです。"}, {"speaker": "A", "jp": "そのファイルであれば、すでに読んでいますので、この場で説明していただかなくても問題ありません。疑問点がでてきたら、確認させてください。"}, {"speaker": "B", "jp": "わかりました。今後、実装中に何かありましたら、遠慮なくいつでも聞いてください。"}]'::jsonb, '今回のプロジェクトの主な内容は何ですか。', '["このアプリをベースに、WebGLを使用してアプリをWeb化し、一部機能の追加・修正を行います。", "昨年のアプリをすべて作り直して、新しいデザインにします。", "デスクトップ版のアプリを、iPad専用のアプリに変えます。", "画面は変えずに、テストだけをやり直します。"]'::jsonb, 0),
  ('8f2e8f8c-5bcf-561a-aefa-33d62cef3b91'::uuid, (select id from jlpt_levels where code = 'IT'), '98000000-0000-0000-0000-000000000007'::uuid, '[{"speaker": "B", "jp": "プロジェクトのメンバーが全員そろいましたので、要件の説明会を始めたいと思います。説明の中で、わかりにくいところや確認しておきたいことがありましたら、その場で質問してください。"}, {"speaker": "A", "jp": "承知しました。よろしくお願いいたします。"}, {"speaker": "B", "jp": "昨年は、デジタル教科書のデスクトップアプリケーションを開発していただき、ありがとうございました。キックオフミーティングで説明した通り、今回はこのアプリをベースに、WebGLを使用してアプリをWeb化し、一部機能の追加・修正を行います。"}, {"speaker": "B", "jp": "まず、今回のWeb版の画面について説明します。お見せしているファイルは昨年開発されたアプリの資料なので、皆さんにとってはなじみのあるものだと思います。新規画面には、「新規」と、Web版で実装しなくてよいものには「Web化対象外」と追記しました。"}, {"speaker": "A", "jp": "はい。「新規」または「Web化対象外」の追記がない場合は、以前のアプリと同じ画面にするということですね。"}, {"speaker": "B", "jp": "その通りです。"}, {"speaker": "B", "jp": "また、機能の修正点がいくつかあるので、別のファイルにまとめました。"}, {"speaker": "A", "jp": "はい。「Web化_修正点」というものですか。"}, {"speaker": "B", "jp": "はい、そうです。"}, {"speaker": "A", "jp": "そのファイルであれば、すでに読んでいますので、この場で説明していただかなくても問題ありません。疑問点がでてきたら、確認させてください。"}, {"speaker": "B", "jp": "わかりました。今後、実装中に何かありましたら、遠慮なくいつでも聞いてください。"}]'::jsonb, 'なぜ「Web化_修正点」の説明が必要ないのですか。', '["そのファイルは今回のプロジェクトに関係がないからです。", "そのファイルをすでに読んでいるからです。", "お客様が後で別の会議で説明するからです。", "そのファイルにはまだ何も書いていないからです。"]'::jsonb, 1),
  ('87bbf544-83b8-5402-8777-ffb38333d36b'::uuid, (select id from jlpt_levels where code = 'IT'), '98000000-0000-0000-0000-000000000008'::uuid, '[{"speaker": "B", "jp": "こんにちは。御社は小巻様のみが参加されるのでしょうか。"}, {"speaker": "B", "jp": "はい、そうです。私だけです。"}, {"speaker": "A", "jp": "弊社は全員そろいましたので会議を始めたいと思います。よろしくお願いいたします。"}, {"speaker": "B", "jp": "はい、よろしくお願いいたします。"}, {"speaker": "A", "jp": "昨日の夕方に進捗の詳細をまとめた WBS と進捗報告書を送付しました。"}, {"speaker": "B", "jp": "はい、受け取ってざっと確認しました。"}, {"speaker": "A", "jp": "それでは、画面共有をして報告いたします。内容は進捗報告、リスク・課題と Q&A の3つです。まず、3.3、3.4 の2つの実装タスクを除いて、全体の進捗は計画通りです。開発環境の調査と構築、パフォーマンス改善は完了しました。"}, {"speaker": "A", "jp": "現在は、画面の実装と結合テスト仕様書作成を進めています。画面の実装は50%、結合テスト仕様書の作成は30%完了しました。進捗の詳細は WBS ファイルをご確認ください。"}, {"speaker": "B", "jp": "承知しました。実装は全体で50%ということでしたが、どの機能も順調に進んでいるのですか。"}, {"speaker": "A", "jp": "現在、4つの機能の実装タスクを並行して進めています。そのうち、1つのタスクは完了しており、1つが実施中、2つが遅延です。"}, {"speaker": "B", "jp": "遅延のタスクがあるんですね。それについて詳しく教えていただけますか。週報を見ると、確かに3.3番の「学習データ保存」は50%、3.4番の「学習の結果」は0%で、赤字になっていますね。"}, {"speaker": "A", "jp": "はい、その通りです。学習データ保存、学習の結果の実装で課題が発生しています。"}]'::jsonb, '昨日、プロジェクトチームは何を送付しましたか。', '["進捗の詳細をまとめたWBSと進捗報告書を送付しました。", "結合テスト仕様書と画面の設計書を送付しました。", "開発環境の調査結果とリスクの一覧を送付しました。", "Q&Aファイルと週報を送付しました。"]'::jsonb, 0),
  ('add76226-acbf-500b-a579-e377436cde39'::uuid, (select id from jlpt_levels where code = 'IT'), '98000000-0000-0000-0000-000000000008'::uuid, '[{"speaker": "B", "jp": "こんにちは。御社は小巻様のみが参加されるのでしょうか。"}, {"speaker": "B", "jp": "はい、そうです。私だけです。"}, {"speaker": "A", "jp": "弊社は全員そろいましたので会議を始めたいと思います。よろしくお願いいたします。"}, {"speaker": "B", "jp": "はい、よろしくお願いいたします。"}, {"speaker": "A", "jp": "昨日の夕方に進捗の詳細をまとめた WBS と進捗報告書を送付しました。"}, {"speaker": "B", "jp": "はい、受け取ってざっと確認しました。"}, {"speaker": "A", "jp": "それでは、画面共有をして報告いたします。内容は進捗報告、リスク・課題と Q&A の3つです。まず、3.3、3.4 の2つの実装タスクを除いて、全体の進捗は計画通りです。開発環境の調査と構築、パフォーマンス改善は完了しました。"}, {"speaker": "A", "jp": "現在は、画面の実装と結合テスト仕様書作成を進めています。画面の実装は50%、結合テスト仕様書の作成は30%完了しました。進捗の詳細は WBS ファイルをご確認ください。"}, {"speaker": "B", "jp": "承知しました。実装は全体で50%ということでしたが、どの機能も順調に進んでいるのですか。"}, {"speaker": "A", "jp": "現在、4つの機能の実装タスクを並行して進めています。そのうち、1つのタスクは完了しており、1つが実施中、2つが遅延です。"}, {"speaker": "B", "jp": "遅延のタスクがあるんですね。それについて詳しく教えていただけますか。週報を見ると、確かに3.3番の「学習データ保存」は50%、3.4番の「学習の結果」は0%で、赤字になっていますね。"}, {"speaker": "A", "jp": "はい、その通りです。学習データ保存、学習の結果の実装で課題が発生しています。"}]'::jsonb, 'プロジェクトでは今、何の作業をしていますか。', '["開発環境の調査と構築を進めています。", "画面の実装と結合テスト仕様書の作成を進めています。", "パフォーマンスの改善と画面のデモを進めています。", "学習データ保存と学習の結果のテストを進めています。"]'::jsonb, 1),
  ('2465c023-fb6c-53e6-92e3-1e838e57de31'::uuid, (select id from jlpt_levels where code = 'IT'), '98000000-0000-0000-0000-000000000008'::uuid, '[{"speaker": "B", "jp": "こんにちは。御社は小巻様のみが参加されるのでしょうか。"}, {"speaker": "B", "jp": "はい、そうです。私だけです。"}, {"speaker": "A", "jp": "弊社は全員そろいましたので会議を始めたいと思います。よろしくお願いいたします。"}, {"speaker": "B", "jp": "はい、よろしくお願いいたします。"}, {"speaker": "A", "jp": "昨日の夕方に進捗の詳細をまとめた WBS と進捗報告書を送付しました。"}, {"speaker": "B", "jp": "はい、受け取ってざっと確認しました。"}, {"speaker": "A", "jp": "それでは、画面共有をして報告いたします。内容は進捗報告、リスク・課題と Q&A の3つです。まず、3.3、3.4 の2つの実装タスクを除いて、全体の進捗は計画通りです。開発環境の調査と構築、パフォーマンス改善は完了しました。"}, {"speaker": "A", "jp": "現在は、画面の実装と結合テスト仕様書作成を進めています。画面の実装は50%、結合テスト仕様書の作成は30%完了しました。進捗の詳細は WBS ファイルをご確認ください。"}, {"speaker": "B", "jp": "承知しました。実装は全体で50%ということでしたが、どの機能も順調に進んでいるのですか。"}, {"speaker": "A", "jp": "現在、4つの機能の実装タスクを並行して進めています。そのうち、1つのタスクは完了しており、1つが実施中、2つが遅延です。"}, {"speaker": "B", "jp": "遅延のタスクがあるんですね。それについて詳しく教えていただけますか。週報を見ると、確かに3.3番の「学習データ保存」は50%、3.4番の「学習の結果」は0%で、赤字になっていますね。"}, {"speaker": "A", "jp": "はい、その通りです。学習データ保存、学習の結果の実装で課題が発生しています。"}]'::jsonb, '週報で赤字になっているタスクについて教えてください。', '["3.3「学習データ保存」は完了しましたが、3.4「学習の結果」は50%です。", "3.3「学習データ保存」は0%、3.4「学習の結果」は50%で、課題が発生しています。", "3.3「学習データ保存」は50%、3.4「学習の結果」は0%で、実装で課題が発生しています。", "3.3も3.4も完了していますが、テストで不具合が出ました。"]'::jsonb, 2),
  ('96bc0334-bd0d-56aa-8007-749b8b8f9f9d'::uuid, (select id from jlpt_levels where code = 'IT'), '98000000-0000-0000-0000-000000000009'::uuid, '[{"speaker": "B", "jp": "メモリ不足の課題が発生していると聞いていますが、状況を教えてもらえますか。"}, {"speaker": "A", "jp": "はい。ここは、以前のデスクトップアプリのときは、静的データをRAMに保存する方法で、問題ありませんでした。ですが、Webの開発では、その方法だとメモリ不足になります。"}, {"speaker": "B", "jp": "メモリ不足が原因で、一部の画面がデスクトップアプリと同じように動作しないのですね。"}, {"speaker": "A", "jp": "はい。そのとおりです。弊社で調査した結果、静的データを使う代わりにindexedDBというAPIにデータを保存すれば、解決することがわかりました。現在、この対策で実装を進めています。"}, {"speaker": "B", "jp": "わかりました。WebではindexedDBを使えば、問題なく動くということですね。それで、全体の進捗には影響しませんか。"}, {"speaker": "A", "jp": "これらのタスクは予定より2人日遅延していますが、代わりに結合テスト仕様書の作成を前倒しして対応しております。そのため、全体の進捗には影響しません。ここの遅延は来週中に取り戻す予定です。"}, {"speaker": "B", "jp": "はい。では引き続き対応していただいて、また何か問題があれば、ご連絡お願いします。"}, {"speaker": "A", "jp": "はい。承知しました。"}, {"speaker": "B", "jp": "他に何か課題はありますか。"}]'::jsonb, '現在、プロジェクトにはどのような課題がありますか。', '["デスクトップアプリの画面が、Webで表示されなくなったことです。", "Webの開発では、静的データをRAMに保存する方法だとメモリ不足になることです。", "indexedDBが使えなくて、データを保存できないことです。", "結合テスト仕様書の作成が、予定より遅れていることです。"]'::jsonb, 1),
  ('8ac18980-8009-5e6f-915e-f6facdb0a8aa'::uuid, (select id from jlpt_levels where code = 'IT'), '98000000-0000-0000-0000-000000000009'::uuid, '[{"speaker": "B", "jp": "メモリ不足の課題が発生していると聞いていますが、状況を教えてもらえますか。"}, {"speaker": "A", "jp": "はい。ここは、以前のデスクトップアプリのときは、静的データをRAMに保存する方法で、問題ありませんでした。ですが、Webの開発では、その方法だとメモリ不足になります。"}, {"speaker": "B", "jp": "メモリ不足が原因で、一部の画面がデスクトップアプリと同じように動作しないのですね。"}, {"speaker": "A", "jp": "はい。そのとおりです。弊社で調査した結果、静的データを使う代わりにindexedDBというAPIにデータを保存すれば、解決することがわかりました。現在、この対策で実装を進めています。"}, {"speaker": "B", "jp": "わかりました。WebではindexedDBを使えば、問題なく動くということですね。それで、全体の進捗には影響しませんか。"}, {"speaker": "A", "jp": "これらのタスクは予定より2人日遅延していますが、代わりに結合テスト仕様書の作成を前倒しして対応しております。そのため、全体の進捗には影響しません。ここの遅延は来週中に取り戻す予定です。"}, {"speaker": "B", "jp": "はい。では引き続き対応していただいて、また何か問題があれば、ご連絡お願いします。"}, {"speaker": "A", "jp": "はい。承知しました。"}, {"speaker": "B", "jp": "他に何か課題はありますか。"}]'::jsonb, 'メモリ不足が原因で、どのような状況が発生していますか。', '["すべての画面が、まったく表示されなくなりました。", "画面の表示は正しいですが、データが古いままになります。", "一部の画面が、デスクトップアプリと同じように動作しません。", "アプリが起動するまでに、とても時間がかかります。"]'::jsonb, 2),
  ('12347803-0793-5da7-a720-17de5c5afa80'::uuid, (select id from jlpt_levels where code = 'IT'), '98000000-0000-0000-0000-000000000009'::uuid, '[{"speaker": "B", "jp": "メモリ不足の課題が発生していると聞いていますが、状況を教えてもらえますか。"}, {"speaker": "A", "jp": "はい。ここは、以前のデスクトップアプリのときは、静的データをRAMに保存する方法で、問題ありませんでした。ですが、Webの開発では、その方法だとメモリ不足になります。"}, {"speaker": "B", "jp": "メモリ不足が原因で、一部の画面がデスクトップアプリと同じように動作しないのですね。"}, {"speaker": "A", "jp": "はい。そのとおりです。弊社で調査した結果、静的データを使う代わりにindexedDBというAPIにデータを保存すれば、解決することがわかりました。現在、この対策で実装を進めています。"}, {"speaker": "B", "jp": "わかりました。WebではindexedDBを使えば、問題なく動くということですね。それで、全体の進捗には影響しませんか。"}, {"speaker": "A", "jp": "これらのタスクは予定より2人日遅延していますが、代わりに結合テスト仕様書の作成を前倒しして対応しております。そのため、全体の進捗には影響しません。ここの遅延は来週中に取り戻す予定です。"}, {"speaker": "B", "jp": "はい。では引き続き対応していただいて、また何か問題があれば、ご連絡お願いします。"}, {"speaker": "A", "jp": "はい。承知しました。"}, {"speaker": "B", "jp": "他に何か課題はありますか。"}]'::jsonb, '課題は全体の進捗に影響していますか。それは、なぜですか。', '["影響します。遅れを取り戻すために、来週の会議を中止するからです。", "影響します。indexedDBの実装がまだ終わっていないからです。", "影響しません。遅れているタスクは、次のリリースで対応するからです。", "影響しません。結合テスト仕様書の作成を前倒しして、遅れは来週中に取り戻す予定だからです。"]'::jsonb, 3),
  ('bbdfba43-1668-57bf-833b-06d2c998df7d'::uuid, (select id from jlpt_levels where code = 'IT'), '98000000-0000-0000-0000-000000000010'::uuid, '[{"speaker": "A", "jp": "最後に１点だけお願いがあるのですが、よろしいですか。"}, {"speaker": "B", "jp": "はい、何でしょう。"}, {"speaker": "A", "jp": "昨日、Q&Aファイルに５番〜８番の４件の質問を追加しましたので、今週金曜日までにご回答いただけますか。"}, {"speaker": "B", "jp": "今まだ時間があるので、すぐ確認して、回答できる範囲で回答したいですが、いかがですか。"}, {"speaker": "A", "jp": "はい、ではQ&Aファイルを映しますので、少しお待ちください。"}, {"speaker": "A", "jp": "映っていますか。"}, {"speaker": "B", "jp": "はい、見えています。"}, {"speaker": "A", "jp": "５番のQ&Aはテスト環境についてです。先日、iPad Airも対象にするというお話でしたが、テストブラウザはSafariのみでよろしいですか。それともChromeもテストしないといけないですか。対象にする場合、テストは最新のバージョンのみで問題ありませんか。それとも一つ前のバージョンもテストする必要がありますか。"}, {"speaker": "B", "jp": "そうですね。Chromeもお願いします。バージョンは、最新のものだけでよいです。"}, {"speaker": "A", "jp": "承知しました。では、次の６番に行きます。アプリを操作するときの動きについて相談させてください。ブラウザでアプリを開くときに、複数のタブやウィンドウで開けないように制限を設けたいです。理由はファイルにも書いた通り、RAMをたくさん使うことになり、パフォーマンスに影響を与える可能性があるからです。"}, {"speaker": "B", "jp": "操作には制限をかけたくないのですが、社内で確認してから回答します。"}, {"speaker": "A", "jp": "承知しました。そろそろ終了時間ですので、残りの質問を含めて、今週中に回答していただけると幸いです。よろしくお願いいたします。"}, {"speaker": "B", "jp": "はい、では本日はここで終わりましょう。ありがとうございました。引き続きよろしくお願いいたします。"}]'::jsonb, 'Q&Aファイルに関して、チームはいつまでに回答を受け取りたいですか。', '["明日までです。", "来週の月曜日までです。", "今週金曜日までです。", "今日の会議が終わるまでです。"]'::jsonb, 2),
  ('affd4f18-81e2-5a8d-a48b-79645d81030e'::uuid, (select id from jlpt_levels where code = 'IT'), '98000000-0000-0000-0000-000000000010'::uuid, '[{"speaker": "A", "jp": "最後に１点だけお願いがあるのですが、よろしいですか。"}, {"speaker": "B", "jp": "はい、何でしょう。"}, {"speaker": "A", "jp": "昨日、Q&Aファイルに５番〜８番の４件の質問を追加しましたので、今週金曜日までにご回答いただけますか。"}, {"speaker": "B", "jp": "今まだ時間があるので、すぐ確認して、回答できる範囲で回答したいですが、いかがですか。"}, {"speaker": "A", "jp": "はい、ではQ&Aファイルを映しますので、少しお待ちください。"}, {"speaker": "A", "jp": "映っていますか。"}, {"speaker": "B", "jp": "はい、見えています。"}, {"speaker": "A", "jp": "５番のQ&Aはテスト環境についてです。先日、iPad Airも対象にするというお話でしたが、テストブラウザはSafariのみでよろしいですか。それともChromeもテストしないといけないですか。対象にする場合、テストは最新のバージョンのみで問題ありませんか。それとも一つ前のバージョンもテストする必要がありますか。"}, {"speaker": "B", "jp": "そうですね。Chromeもお願いします。バージョンは、最新のものだけでよいです。"}, {"speaker": "A", "jp": "承知しました。では、次の６番に行きます。アプリを操作するときの動きについて相談させてください。ブラウザでアプリを開くときに、複数のタブやウィンドウで開けないように制限を設けたいです。理由はファイルにも書いた通り、RAMをたくさん使うことになり、パフォーマンスに影響を与える可能性があるからです。"}, {"speaker": "B", "jp": "操作には制限をかけたくないのですが、社内で確認してから回答します。"}, {"speaker": "A", "jp": "承知しました。そろそろ終了時間ですので、残りの質問を含めて、今週中に回答していただけると幸いです。よろしくお願いいたします。"}, {"speaker": "B", "jp": "はい、では本日はここで終わりましょう。ありがとうございました。引き続きよろしくお願いいたします。"}]'::jsonb, 'なぜチームは、ブラウザでアプリを開くときの操作に制限を設けたいのですか。', '["複数のタブで開くと、お客様のデータが他の人に見えてしまうからです。", "ブラウザのバージョンが古いと、アプリが正しく動かないからです。", "iPad Airでは、複数のウィンドウを開くことができないからです。", "複数のタブやウィンドウで開くと、RAMをたくさん使い、パフォーマンスに影響を与える可能性があるからです。"]'::jsonb, 3),
  ('9c205a87-e413-5065-af0c-fba3f604fd33'::uuid, (select id from jlpt_levels where code = 'IT'), '98000000-0000-0000-0000-000000000010'::uuid, '[{"speaker": "A", "jp": "最後に１点だけお願いがあるのですが、よろしいですか。"}, {"speaker": "B", "jp": "はい、何でしょう。"}, {"speaker": "A", "jp": "昨日、Q&Aファイルに５番〜８番の４件の質問を追加しましたので、今週金曜日までにご回答いただけますか。"}, {"speaker": "B", "jp": "今まだ時間があるので、すぐ確認して、回答できる範囲で回答したいですが、いかがですか。"}, {"speaker": "A", "jp": "はい、ではQ&Aファイルを映しますので、少しお待ちください。"}, {"speaker": "A", "jp": "映っていますか。"}, {"speaker": "B", "jp": "はい、見えています。"}, {"speaker": "A", "jp": "５番のQ&Aはテスト環境についてです。先日、iPad Airも対象にするというお話でしたが、テストブラウザはSafariのみでよろしいですか。それともChromeもテストしないといけないですか。対象にする場合、テストは最新のバージョンのみで問題ありませんか。それとも一つ前のバージョンもテストする必要がありますか。"}, {"speaker": "B", "jp": "そうですね。Chromeもお願いします。バージョンは、最新のものだけでよいです。"}, {"speaker": "A", "jp": "承知しました。では、次の６番に行きます。アプリを操作するときの動きについて相談させてください。ブラウザでアプリを開くときに、複数のタブやウィンドウで開けないように制限を設けたいです。理由はファイルにも書いた通り、RAMをたくさん使うことになり、パフォーマンスに影響を与える可能性があるからです。"}, {"speaker": "B", "jp": "操作には制限をかけたくないのですが、社内で確認してから回答します。"}, {"speaker": "A", "jp": "承知しました。そろそろ終了時間ですので、残りの質問を含めて、今週中に回答していただけると幸いです。よろしくお願いいたします。"}, {"speaker": "B", "jp": "はい、では本日はここで終わりましょう。ありがとうございました。引き続きよろしくお願いいたします。"}]'::jsonb, 'お客様は、アプリの操作について何と言っていますか。', '["操作には制限をかけたくないので、社内で確認してから回答すると言っています。", "制限をかけることに賛成なので、すぐに対応してほしいと言っています。", "制限は必要ないので、今日中に回答すると言っています。", "Chromeでは制限をかけてもよいが、Safariでは困ると言っています。"]'::jsonb, 0),
  ('8fab0256-c351-556c-9262-602166dded8a'::uuid, (select id from jlpt_levels where code = 'IT'), '98000000-0000-0000-0000-000000000011'::uuid, '[{"speaker": "A", "jp": "では、学習結果確認機能の詳細画面のデモを始めます。よろしくお願いします。"}, {"speaker": "B", "jp": "はい、よろしくお願いします。"}, {"speaker": "A", "jp": "詳細画面では、要件通り、画像を上部に配置しています。画面レイアウトはこれでよいかご確認お願いします。"}, {"speaker": "B", "jp": "うーん。やはり、画像にボタンが重なってしまうのは避けたいですね。ここは、そうならないように対応してもらえますか。"}, {"speaker": "A", "jp": "そうですね…。ボタンが重ならないように、画像の表示領域を小さくして対応することはできますが、いかがですか。"}, {"speaker": "B", "jp": "可能であれば、表示領域は変更しないようにしたいです。デフォルトの画像サイズを小さくして、対応するわけにはいかないですか。"}, {"speaker": "A", "jp": "実は、アプリの表示枠は画面の縦横の比率に固定しているので、その案での対応は難しいかと思います。では、一度持ち帰って、技術的に実現可能か検討してみます。その結果を次の定例会のときに報告してもよろしいですか。"}, {"speaker": "B", "jp": "はい、お願いします。それと、対応にかかる工数も見積もって報告してください。"}, {"speaker": "A", "jp": "はい、承知しました。変更する場合は、いくつか修正する必要が出てくると思います。画像の拡大・縮小やペンツールなどです。デスクトップ版とWeb版の両方で変更点と変更の工数をまとめて報告します。"}, {"speaker": "B", "jp": "はい、お待ちしています。"}]'::jsonb, '本日の製品デモの目的は何ですか。', '["新しいデザインのボタンを、お客様に選んでもらうことです。", "学習結果確認機能の見積りを、お客様に報告することです。", "デスクトップ版とWeb版の違いを説明することです。", "学習結果確認機能の詳細画面のデモをして、お客様に確認してもらうことです。"]'::jsonb, 3),
  ('e49c6adc-8b2a-56ac-87ff-8044d015c6df'::uuid, (select id from jlpt_levels where code = 'IT'), '98000000-0000-0000-0000-000000000011'::uuid, '[{"speaker": "A", "jp": "では、学習結果確認機能の詳細画面のデモを始めます。よろしくお願いします。"}, {"speaker": "B", "jp": "はい、よろしくお願いします。"}, {"speaker": "A", "jp": "詳細画面では、要件通り、画像を上部に配置しています。画面レイアウトはこれでよいかご確認お願いします。"}, {"speaker": "B", "jp": "うーん。やはり、画像にボタンが重なってしまうのは避けたいですね。ここは、そうならないように対応してもらえますか。"}, {"speaker": "A", "jp": "そうですね…。ボタンが重ならないように、画像の表示領域を小さくして対応することはできますが、いかがですか。"}, {"speaker": "B", "jp": "可能であれば、表示領域は変更しないようにしたいです。デフォルトの画像サイズを小さくして、対応するわけにはいかないですか。"}, {"speaker": "A", "jp": "実は、アプリの表示枠は画面の縦横の比率に固定しているので、その案での対応は難しいかと思います。では、一度持ち帰って、技術的に実現可能か検討してみます。その結果を次の定例会のときに報告してもよろしいですか。"}, {"speaker": "B", "jp": "はい、お願いします。それと、対応にかかる工数も見積もって報告してください。"}, {"speaker": "A", "jp": "はい、承知しました。変更する場合は、いくつか修正する必要が出てくると思います。画像の拡大・縮小やペンツールなどです。デスクトップ版とWeb版の両方で変更点と変更の工数をまとめて報告します。"}, {"speaker": "B", "jp": "はい、お待ちしています。"}]'::jsonb, '詳細画面のレイアウトについて、お客様は何を希望していますか。', '["表示領域は変えずに、デフォルトの画像サイズを小さくして、ボタンが画像に重ならないようにしてほしいと言っています。", "画像を大きくして、ボタンを画面の外に出してほしいと言っています。", "ボタンを小さくして、画像に重なってもよいと言っています。", "画像の表示領域を小さくして、ボタンを増やしてほしいと言っています。"]'::jsonb, 0),
  ('f6fd5128-c152-58d5-998d-29a64a2f6a12'::uuid, (select id from jlpt_levels where code = 'IT'), '98000000-0000-0000-0000-000000000011'::uuid, '[{"speaker": "A", "jp": "では、学習結果確認機能の詳細画面のデモを始めます。よろしくお願いします。"}, {"speaker": "B", "jp": "はい、よろしくお願いします。"}, {"speaker": "A", "jp": "詳細画面では、要件通り、画像を上部に配置しています。画面レイアウトはこれでよいかご確認お願いします。"}, {"speaker": "B", "jp": "うーん。やはり、画像にボタンが重なってしまうのは避けたいですね。ここは、そうならないように対応してもらえますか。"}, {"speaker": "A", "jp": "そうですね…。ボタンが重ならないように、画像の表示領域を小さくして対応することはできますが、いかがですか。"}, {"speaker": "B", "jp": "可能であれば、表示領域は変更しないようにしたいです。デフォルトの画像サイズを小さくして、対応するわけにはいかないですか。"}, {"speaker": "A", "jp": "実は、アプリの表示枠は画面の縦横の比率に固定しているので、その案での対応は難しいかと思います。では、一度持ち帰って、技術的に実現可能か検討してみます。その結果を次の定例会のときに報告してもよろしいですか。"}, {"speaker": "B", "jp": "はい、お願いします。それと、対応にかかる工数も見積もって報告してください。"}, {"speaker": "A", "jp": "はい、承知しました。変更する場合は、いくつか修正する必要が出てくると思います。画像の拡大・縮小やペンツールなどです。デスクトップ版とWeb版の両方で変更点と変更の工数をまとめて報告します。"}, {"speaker": "B", "jp": "はい、お待ちしています。"}]'::jsonb, '詳細画面のレイアウトを変更する場合はどのような修正が必要ですか。', '["画面の色とフォントを、すべて変える必要があります。", "画像の拡大・縮小やペンツールなど、いくつか修正が必要です。", "ログイン機能とデータ保存機能を、作り直す必要があります。", "iPad版だけを修正すれば、ほかは変えなくても大丈夫です。"]'::jsonb, 1),
  ('4185d624-dd24-5edb-9fb5-d0bea0358006'::uuid, (select id from jlpt_levels where code = 'IT'), '98000000-0000-0000-0000-000000000012'::uuid, '[{"speaker": "A", "jp": "小巻さん、スケジュールについて相談したいことがありますが、お時間よろしいですか。"}, {"speaker": "B", "jp": "はい。いいですよ。"}, {"speaker": "A", "jp": "Q&Aの６番に関してです。同じブラウザで複数ウィンドウを開くのに制限をかけない、というご要望でしたが、これに対応するには予定よりも時間がかかりそうです。"}, {"speaker": "B", "jp": "そうですか。時間がかかるということですが、今回のリリーススケジュールには影響しますか。"}, {"speaker": "A", "jp": "それが、スケジュールに影響しそうなので、ご相談したいです。制限をかけないように対応した場合は、今回のリリースに間に合わないと思っています。"}, {"speaker": "B", "jp": "うーん…。そうですか。対応には、どの程度工数がかかる見込みですか。"}, {"speaker": "A", "jp": "はい、対応工数を見積もった結果、少なくとも10人日かかる見込みです。そこで、ご相談ですが、今回のリリースは制限を設けたバージョンを納品し、次回のリリースの際に制限なしのバージョンを納品したいです。それで、ご承認いただけないでしょうか。"}, {"speaker": "B", "jp": "１点確認しておきたいのですが、見積り工数は、テストも含めた工数ですか。"}, {"speaker": "A", "jp": "はい、そうです。そのうち３人日はテスト工数です。"}, {"speaker": "B", "jp": "状況についてはわかりました。受け入れテストの日程も近いので、一旦、担当者とも相談します。回答は早いほうがいいですね。"}, {"speaker": "A", "jp": "はい、できれば、明日中にご回答いただけないでしょうか。どうぞよろしくお願いいたします。"}]'::jsonb, 'チームは何の対応に予定よりも時間がかかりそうだと言っていましたか。', '["同じブラウザで複数ウィンドウを開くのに制限をかけない対応です。", "iPad版で画像を10枚まで保存できるようにする対応です。", "テスト環境にChromeを追加する対応です。", "インストール手順書にアンインストールの手順を書く対応です。"]'::jsonb, 0),
  ('29bc52fa-eb32-5f87-8f11-a322bbcd10d8'::uuid, (select id from jlpt_levels where code = 'IT'), '98000000-0000-0000-0000-000000000012'::uuid, '[{"speaker": "A", "jp": "小巻さん、スケジュールについて相談したいことがありますが、お時間よろしいですか。"}, {"speaker": "B", "jp": "はい。いいですよ。"}, {"speaker": "A", "jp": "Q&Aの６番に関してです。同じブラウザで複数ウィンドウを開くのに制限をかけない、というご要望でしたが、これに対応するには予定よりも時間がかかりそうです。"}, {"speaker": "B", "jp": "そうですか。時間がかかるということですが、今回のリリーススケジュールには影響しますか。"}, {"speaker": "A", "jp": "それが、スケジュールに影響しそうなので、ご相談したいです。制限をかけないように対応した場合は、今回のリリースに間に合わないと思っています。"}, {"speaker": "B", "jp": "うーん…。そうですか。対応には、どの程度工数がかかる見込みですか。"}, {"speaker": "A", "jp": "はい、対応工数を見積もった結果、少なくとも10人日かかる見込みです。そこで、ご相談ですが、今回のリリースは制限を設けたバージョンを納品し、次回のリリースの際に制限なしのバージョンを納品したいです。それで、ご承認いただけないでしょうか。"}, {"speaker": "B", "jp": "１点確認しておきたいのですが、見積り工数は、テストも含めた工数ですか。"}, {"speaker": "A", "jp": "はい、そうです。そのうち３人日はテスト工数です。"}, {"speaker": "B", "jp": "状況についてはわかりました。受け入れテストの日程も近いので、一旦、担当者とも相談します。回答は早いほうがいいですね。"}, {"speaker": "A", "jp": "はい、できれば、明日中にご回答いただけないでしょうか。どうぞよろしくお願いいたします。"}]'::jsonb, 'チームは見積り工数にテスト工数も含めましたか。含めた場合、テスト工数はどの程度でしたか。', '["はい。少なくとも3人日で、そのうち10人日がテスト工数です。", "はい。少なくとも10人日で、そのうち3人日がテスト工数です。", "いいえ。テスト工数は含まず、10人日は開発だけの工数です。", "はい。少なくとも10人日で、テスト工数は5人日です。"]'::jsonb, 1),
  ('1765f917-93c1-5d9a-8478-12a8b7aac0ae'::uuid, (select id from jlpt_levels where code = 'IT'), '98000000-0000-0000-0000-000000000012'::uuid, '[{"speaker": "A", "jp": "小巻さん、スケジュールについて相談したいことがありますが、お時間よろしいですか。"}, {"speaker": "B", "jp": "はい。いいですよ。"}, {"speaker": "A", "jp": "Q&Aの６番に関してです。同じブラウザで複数ウィンドウを開くのに制限をかけない、というご要望でしたが、これに対応するには予定よりも時間がかかりそうです。"}, {"speaker": "B", "jp": "そうですか。時間がかかるということですが、今回のリリーススケジュールには影響しますか。"}, {"speaker": "A", "jp": "それが、スケジュールに影響しそうなので、ご相談したいです。制限をかけないように対応した場合は、今回のリリースに間に合わないと思っています。"}, {"speaker": "B", "jp": "うーん…。そうですか。対応には、どの程度工数がかかる見込みですか。"}, {"speaker": "A", "jp": "はい、対応工数を見積もった結果、少なくとも10人日かかる見込みです。そこで、ご相談ですが、今回のリリースは制限を設けたバージョンを納品し、次回のリリースの際に制限なしのバージョンを納品したいです。それで、ご承認いただけないでしょうか。"}, {"speaker": "B", "jp": "１点確認しておきたいのですが、見積り工数は、テストも含めた工数ですか。"}, {"speaker": "A", "jp": "はい、そうです。そのうち３人日はテスト工数です。"}, {"speaker": "B", "jp": "状況についてはわかりました。受け入れテストの日程も近いので、一旦、担当者とも相談します。回答は早いほうがいいですね。"}, {"speaker": "A", "jp": "はい、できれば、明日中にご回答いただけないでしょうか。どうぞよろしくお願いいたします。"}]'::jsonb, 'チームは次回のリリースで制限なしのバージョンを納品することを提案しましたが、お客様は合意しましたか。それはなぜですか。', '["はい。制限なしのバージョンを次回に納品することに、すぐ合意しました。", "いいえ。制限を設けたバージョンは、納品してはいけないと言いました。", "いいえ、すぐには合意していません。受け入れテストの日程が近いので、担当者と相談すると言っています。", "はい。ただし、10人日より短い工数にしてほしいと言いました。"]'::jsonb, 2),
  ('16950d1d-f691-553e-a0fa-601cdbb81218'::uuid, (select id from jlpt_levels where code = 'IT'), '98000000-0000-0000-0000-000000000013'::uuid, '[{"speaker": "B", "jp": "昨日は納品していただきありがとうございました。では、今回の納品についてご説明いただけますか。"}, {"speaker": "A", "jp": "はい。承知しました。では、リリースノートの記載内容に沿って説明いたします。"}, {"speaker": "B", "jp": "１点だけお願いですが、デモのときに弊社からあげた要望や御社からのご提案があったと思いますので、その対応についても教えてください。"}, {"speaker": "A", "jp": "はい。まず、納品物ですが、ソースコードとソースコードからビルドしたアプリケーション、そして、ドキュメントをこちらのフォルダに配置しました。ご要望に応じて、インストール手順書には、アンインストールの手順についても記載しています。"}, {"speaker": "B", "jp": "はい、拝見したところ、手順書の中で少しわかりにくい記載があるので、後ほど確認させてください。"}, {"speaker": "A", "jp": "今回は、開発の中でいくつか制限事項も残っています。それについて説明します。iPad版の学習データ保存機能では、お気に入り画面に画像が３枚以上あると、ページが再読み込みされます。また、iPad版のお気に入りに登録できる画像は最大２MBで10枚までです。"}, {"speaker": "B", "jp": "はい。これは以前からご説明がありましたね。"}, {"speaker": "A", "jp": "はい。見積りの際に説明した通り、端末のハードウェアのスペックによるものです。機能は実行できますが、デスクトップ版と比べると動作が重くなります。そこで、端末のRAMは４GB以上を推奨しています。"}, {"speaker": "B", "jp": "はい、これに関しては弊社でも承知しています。"}]'::jsonb, '納品物には何が含まれますか。', '["ソースコードとテスト環境のサーバーです。", "ソースコード、ソースコードからビルドしたアプリケーション、ドキュメントです。", "アプリケーションと学習データのバックアップです。", "ドキュメントとiPad用の端末です。"]'::jsonb, 1),
  ('1b86c012-fa40-5ad9-ad6d-6d4e7e23acd9'::uuid, (select id from jlpt_levels where code = 'IT'), '98000000-0000-0000-0000-000000000013'::uuid, '[{"speaker": "B", "jp": "昨日は納品していただきありがとうございました。では、今回の納品についてご説明いただけますか。"}, {"speaker": "A", "jp": "はい。承知しました。では、リリースノートの記載内容に沿って説明いたします。"}, {"speaker": "B", "jp": "１点だけお願いですが、デモのときに弊社からあげた要望や御社からのご提案があったと思いますので、その対応についても教えてください。"}, {"speaker": "A", "jp": "はい。まず、納品物ですが、ソースコードとソースコードからビルドしたアプリケーション、そして、ドキュメントをこちらのフォルダに配置しました。ご要望に応じて、インストール手順書には、アンインストールの手順についても記載しています。"}, {"speaker": "B", "jp": "はい、拝見したところ、手順書の中で少しわかりにくい記載があるので、後ほど確認させてください。"}, {"speaker": "A", "jp": "今回は、開発の中でいくつか制限事項も残っています。それについて説明します。iPad版の学習データ保存機能では、お気に入り画面に画像が３枚以上あると、ページが再読み込みされます。また、iPad版のお気に入りに登録できる画像は最大２MBで10枚までです。"}, {"speaker": "B", "jp": "はい。これは以前からご説明がありましたね。"}, {"speaker": "A", "jp": "はい。見積りの際に説明した通り、端末のハードウェアのスペックによるものです。機能は実行できますが、デスクトップ版と比べると動作が重くなります。そこで、端末のRAMは４GB以上を推奨しています。"}, {"speaker": "B", "jp": "はい、これに関しては弊社でも承知しています。"}]'::jsonb, '今回の納品にはどのような制限事項が残っていますか。', '["iPad版でもデスクトップ版でも、ログインができません。", "お気に入り画面に画像が10枚以上あると、アプリが終了します。", "iPad版の学習データ保存機能で、お気に入り画面に画像が3枚以上あるとページが再読み込みされ、登録できる画像も最大2MBで10枚までです。", "登録できる画像は、最大10MBで2枚までです。"]'::jsonb, 2),
  ('cce323ac-85a5-5fca-a7f3-663521b557f6'::uuid, (select id from jlpt_levels where code = 'IT'), '98000000-0000-0000-0000-000000000013'::uuid, '[{"speaker": "B", "jp": "昨日は納品していただきありがとうございました。では、今回の納品についてご説明いただけますか。"}, {"speaker": "A", "jp": "はい。承知しました。では、リリースノートの記載内容に沿って説明いたします。"}, {"speaker": "B", "jp": "１点だけお願いですが、デモのときに弊社からあげた要望や御社からのご提案があったと思いますので、その対応についても教えてください。"}, {"speaker": "A", "jp": "はい。まず、納品物ですが、ソースコードとソースコードからビルドしたアプリケーション、そして、ドキュメントをこちらのフォルダに配置しました。ご要望に応じて、インストール手順書には、アンインストールの手順についても記載しています。"}, {"speaker": "B", "jp": "はい、拝見したところ、手順書の中で少しわかりにくい記載があるので、後ほど確認させてください。"}, {"speaker": "A", "jp": "今回は、開発の中でいくつか制限事項も残っています。それについて説明します。iPad版の学習データ保存機能では、お気に入り画面に画像が３枚以上あると、ページが再読み込みされます。また、iPad版のお気に入りに登録できる画像は最大２MBで10枚までです。"}, {"speaker": "B", "jp": "はい。これは以前からご説明がありましたね。"}, {"speaker": "A", "jp": "はい。見積りの際に説明した通り、端末のハードウェアのスペックによるものです。機能は実行できますが、デスクトップ版と比べると動作が重くなります。そこで、端末のRAMは４GB以上を推奨しています。"}, {"speaker": "B", "jp": "はい、これに関しては弊社でも承知しています。"}]'::jsonb, 'チームは見積りの時に、質問２の制限事項についてどのようなことを言っていましたか。', '["アプリの不具合なので、次のリリースですぐ直すと説明しました。", "お客様の設定が原因なので、設定を変えてほしいと説明しました。", "端末のRAMは2GBあれば十分だと説明しました。", "端末のハードウェアのスペックによるもので、RAMは4GB以上を推奨すると説明しました。"]'::jsonb, 3),
  ('787ae3ed-b8d1-5597-97bb-c7e9b32169ca'::uuid, (select id from jlpt_levels where code = 'IT'), '98000000-0000-0000-0000-000000000014'::uuid, '[{"speaker": "B", "jp": "リーさん、今回のUATサポートでお願いしたいことがありますが、いいですか。"}, {"speaker": "A", "jp": "はい。なんでしょうか。"}, {"speaker": "B", "jp": "先日、成果物を受け取りました。これから受入テストを行っていきます。そこで、不具合が出た場合の体制について、念のためもう一度聞かせてください。"}, {"speaker": "A", "jp": "はい。定例会のときにも相談しましたが、受入テストで検出された不具合は、まず私が原因を分析することになっています。"}, {"speaker": "B", "jp": "そうでしたね。その後、どちらで対応するのか切り分けるのですね。"}, {"speaker": "A", "jp": "はい、その通りです。分析に加えて、私が対応するものとオフショアが対応するものの切り分けもします。再現手順についても確認します。確認に際して分からないことがあったら、山本さんにお聞きしてもよろしいですか。"}, {"speaker": "B", "jp": "もちろん、いいですよ。困ったときは、いつでも声をかけてください。"}, {"speaker": "B", "jp": "不具合が何件か同時に発生した場合は、まず不具合管理システムに登録します。その後、一旦、弊社で対応の優先順位を決めて、連絡します。"}, {"speaker": "B", "jp": "ですが、リーさんが分析をしたときに優先順位を変えたいものがありましたら、相談に来てください。"}, {"speaker": "A", "jp": "承知しました。そう言えば、先日、仕様を少し変えたいというお話がありましたが、具体的に教えていただけますか。"}, {"speaker": "B", "jp": "あ、そうですね。その件に関わる資料を準備していますので、午後、相談しましょう。どれぐらい時間がかかるかを教えていただきたいです。"}, {"speaker": "A", "jp": "承知しました。準備されたら、お声がけください。よろしくお願いいたします。"}]'::jsonb, '受入テストで不具合を検出した場合にリーさんは何をしますか。', '["まず不具合管理システムに登録して、優先順位を決めます。", "すぐにオフショアに連絡して、修正してもらいます。", "まず原因を分析し、対応する担当を切り分け、再現手順も確認します。", "お客様に、どの不具合から直すかを聞きます。"]'::jsonb, 2),
  ('7d511428-c899-5928-878f-5cd1dd4b3e7e'::uuid, (select id from jlpt_levels where code = 'IT'), '98000000-0000-0000-0000-000000000014'::uuid, '[{"speaker": "B", "jp": "リーさん、今回のUATサポートでお願いしたいことがありますが、いいですか。"}, {"speaker": "A", "jp": "はい。なんでしょうか。"}, {"speaker": "B", "jp": "先日、成果物を受け取りました。これから受入テストを行っていきます。そこで、不具合が出た場合の体制について、念のためもう一度聞かせてください。"}, {"speaker": "A", "jp": "はい。定例会のときにも相談しましたが、受入テストで検出された不具合は、まず私が原因を分析することになっています。"}, {"speaker": "B", "jp": "そうでしたね。その後、どちらで対応するのか切り分けるのですね。"}, {"speaker": "A", "jp": "はい、その通りです。分析に加えて、私が対応するものとオフショアが対応するものの切り分けもします。再現手順についても確認します。確認に際して分からないことがあったら、山本さんにお聞きしてもよろしいですか。"}, {"speaker": "B", "jp": "もちろん、いいですよ。困ったときは、いつでも声をかけてください。"}, {"speaker": "B", "jp": "不具合が何件か同時に発生した場合は、まず不具合管理システムに登録します。その後、一旦、弊社で対応の優先順位を決めて、連絡します。"}, {"speaker": "B", "jp": "ですが、リーさんが分析をしたときに優先順位を変えたいものがありましたら、相談に来てください。"}, {"speaker": "A", "jp": "承知しました。そう言えば、先日、仕様を少し変えたいというお話がありましたが、具体的に教えていただけますか。"}, {"speaker": "B", "jp": "あ、そうですね。その件に関わる資料を準備していますので、午後、相談しましょう。どれぐらい時間がかかるかを教えていただきたいです。"}, {"speaker": "A", "jp": "承知しました。準備されたら、お声がけください。よろしくお願いいたします。"}]'::jsonb, '複数の不具合が発生した場合の対応について教えてください。', '["まずリーさんが原因を分析して、優先順位を決めます。", "不具合がすべて直るまで、登録しないで待ちます。", "オフショアが優先順位を決めて、お客様に連絡します。", "まず不具合管理システムに登録します。その後、お客様側で対応の優先順位を決めて連絡します。"]'::jsonb, 3),
  ('a0df3a64-2003-5161-ad01-4b857f293302'::uuid, (select id from jlpt_levels where code = 'IT'), '98000000-0000-0000-0000-000000000014'::uuid, '[{"speaker": "B", "jp": "リーさん、今回のUATサポートでお願いしたいことがありますが、いいですか。"}, {"speaker": "A", "jp": "はい。なんでしょうか。"}, {"speaker": "B", "jp": "先日、成果物を受け取りました。これから受入テストを行っていきます。そこで、不具合が出た場合の体制について、念のためもう一度聞かせてください。"}, {"speaker": "A", "jp": "はい。定例会のときにも相談しましたが、受入テストで検出された不具合は、まず私が原因を分析することになっています。"}, {"speaker": "B", "jp": "そうでしたね。その後、どちらで対応するのか切り分けるのですね。"}, {"speaker": "A", "jp": "はい、その通りです。分析に加えて、私が対応するものとオフショアが対応するものの切り分けもします。再現手順についても確認します。確認に際して分からないことがあったら、山本さんにお聞きしてもよろしいですか。"}, {"speaker": "B", "jp": "もちろん、いいですよ。困ったときは、いつでも声をかけてください。"}, {"speaker": "B", "jp": "不具合が何件か同時に発生した場合は、まず不具合管理システムに登録します。その後、一旦、弊社で対応の優先順位を決めて、連絡します。"}, {"speaker": "B", "jp": "ですが、リーさんが分析をしたときに優先順位を変えたいものがありましたら、相談に来てください。"}, {"speaker": "A", "jp": "承知しました。そう言えば、先日、仕様を少し変えたいというお話がありましたが、具体的に教えていただけますか。"}, {"speaker": "B", "jp": "あ、そうですね。その件に関わる資料を準備していますので、午後、相談しましょう。どれぐらい時間がかかるかを教えていただきたいです。"}, {"speaker": "A", "jp": "承知しました。準備されたら、お声がけください。よろしくお願いいたします。"}]'::jsonb, 'リーさんが分析をしたときに優先順位を変えたい場合はどうしますか。', '["優先順位を変えたいものがあれば、お客様に相談に行きます。", "何も言わずに、リーさんが優先順位を変えます。", "山本さんに、代わりに決めてもらいます。", "次の定例会まで待ってから、報告します。"]'::jsonb, 0),
  ('6e427fb1-e3be-5efd-bc7a-e1d3df8f23f2'::uuid, (select id from jlpt_levels where code = 'IT'), '98000000-0000-0000-0000-000000000015'::uuid, '[{"speaker": "B", "jp": "皆さん、ちょっといいですか。作業の手を止めてこちらへ集まってください。"}, {"speaker": "B", "jp": "デジタル教科書アプリの受入テストと展開も無事終わりました。本日はリーさんのオンサイト最終日です。リーさん、これまで約４か月間お疲れさまでした。"}, {"speaker": "A", "jp": "はい、皆様、オンサイト中はいろいろとお世話になり、ありがとうございました。おかげさまで、受入テストの間、大きな不具合もなく、本日を迎えることができました。"}, {"speaker": "B", "jp": "リーさんがいてくれたので、技術面で課題が出てきたときもスムーズに会話ができ、対応も早かったですね。来週は振り返り会議をすることになっていますが、そこでも良かった点として報告させてもらいます。"}, {"speaker": "A", "jp": "ありがとうございます。本日の定例会で話があった通り、帰国したらチーム全員で良かった点、改善すべき点について相談し、まとめます。"}, {"speaker": "B", "jp": "はい、弊社でもまとめておきますので、来週の会議では、今後のプロジェクトに向けて見直すべきところについても検討しましょう。"}, {"speaker": "B", "jp": "現在は調整中で、まだ確定していませんが、次はもう少し規模の大きなプロジェクトを実施する予定です。"}, {"speaker": "B", "jp": "確定すれば、クラウドの人材など要員追加を依頼することになると思います。詳しいことが決まったら、また御社に連絡しますね。"}, {"speaker": "A", "jp": "はい。こちらこそよろしくお願いいたします。"}]'::jsonb, '受入テストでは、不具合が発生しましたか。', '["はい。大きな不具合が何件かありました。", "はい。展開のときに不具合が出ました。", "いいえ。まだ受入テストが始まっていません。", "いいえ。大きな不具合はありませんでした。"]'::jsonb, 3),
  ('d681485a-f165-52a4-a93e-ba58b3663f58'::uuid, (select id from jlpt_levels where code = 'IT'), '98000000-0000-0000-0000-000000000015'::uuid, '[{"speaker": "B", "jp": "皆さん、ちょっといいですか。作業の手を止めてこちらへ集まってください。"}, {"speaker": "B", "jp": "デジタル教科書アプリの受入テストと展開も無事終わりました。本日はリーさんのオンサイト最終日です。リーさん、これまで約４か月間お疲れさまでした。"}, {"speaker": "A", "jp": "はい、皆様、オンサイト中はいろいろとお世話になり、ありがとうございました。おかげさまで、受入テストの間、大きな不具合もなく、本日を迎えることができました。"}, {"speaker": "B", "jp": "リーさんがいてくれたので、技術面で課題が出てきたときもスムーズに会話ができ、対応も早かったですね。来週は振り返り会議をすることになっていますが、そこでも良かった点として報告させてもらいます。"}, {"speaker": "A", "jp": "ありがとうございます。本日の定例会で話があった通り、帰国したらチーム全員で良かった点、改善すべき点について相談し、まとめます。"}, {"speaker": "B", "jp": "はい、弊社でもまとめておきますので、来週の会議では、今後のプロジェクトに向けて見直すべきところについても検討しましょう。"}, {"speaker": "B", "jp": "現在は調整中で、まだ確定していませんが、次はもう少し規模の大きなプロジェクトを実施する予定です。"}, {"speaker": "B", "jp": "確定すれば、クラウドの人材など要員追加を依頼することになると思います。詳しいことが決まったら、また御社に連絡しますね。"}, {"speaker": "A", "jp": "はい。こちらこそよろしくお願いいたします。"}]'::jsonb, '来週の振り返り会議でオフショアチームは何をしますか。', '["良かった点と改善すべき点について相談し、まとめます。", "新しいプロジェクトの見積りを作ります。", "クラウドの人材を追加で探します。", "受入テストの結果を、お客様に報告します。"]'::jsonb, 0),
  ('a4ef6713-40b1-5cd3-b0a5-f20174e9fc22'::uuid, (select id from jlpt_levels where code = 'IT'), '98000000-0000-0000-0000-000000000015'::uuid, '[{"speaker": "B", "jp": "皆さん、ちょっといいですか。作業の手を止めてこちらへ集まってください。"}, {"speaker": "B", "jp": "デジタル教科書アプリの受入テストと展開も無事終わりました。本日はリーさんのオンサイト最終日です。リーさん、これまで約４か月間お疲れさまでした。"}, {"speaker": "A", "jp": "はい、皆様、オンサイト中はいろいろとお世話になり、ありがとうございました。おかげさまで、受入テストの間、大きな不具合もなく、本日を迎えることができました。"}, {"speaker": "B", "jp": "リーさんがいてくれたので、技術面で課題が出てきたときもスムーズに会話ができ、対応も早かったですね。来週は振り返り会議をすることになっていますが、そこでも良かった点として報告させてもらいます。"}, {"speaker": "A", "jp": "ありがとうございます。本日の定例会で話があった通り、帰国したらチーム全員で良かった点、改善すべき点について相談し、まとめます。"}, {"speaker": "B", "jp": "はい、弊社でもまとめておきますので、来週の会議では、今後のプロジェクトに向けて見直すべきところについても検討しましょう。"}, {"speaker": "B", "jp": "現在は調整中で、まだ確定していませんが、次はもう少し規模の大きなプロジェクトを実施する予定です。"}, {"speaker": "B", "jp": "確定すれば、クラウドの人材など要員追加を依頼することになると思います。詳しいことが決まったら、また御社に連絡しますね。"}, {"speaker": "A", "jp": "はい。こちらこそよろしくお願いいたします。"}]'::jsonb, '次のプロジェクトの実施が確定したら、何が必要になると言っていましたか。', '["新しい開発環境とソースコードが必要になると言っています。", "クラウドの人材など、要員追加が必要になると言っています。", "今より小さいチームで十分だと言っています。", "お客様の会社にオンサイトする人が必要だと言っています。"]'::jsonb, 1);
